  "app/_components/agent-chat.tsx":
    '"use client";\r\n\r\nimport { useEveAgent } from "eve/react";\r\nimport { AlertCircleIcon } from "lucide-react";\r\nimport {\r\n  Conversation,\r\n  ConversationContent,\r\n  ConversationScrollButton,\r\n} from "@/components/ai-elements/conversation";\r\nimport {\r\n  PromptInput,\r\n  type PromptInputMessage,\r\n  PromptInputSubmit,\r\n  PromptInputTextarea,\r\n} from "@/components/ai-elements/prompt-input";\r\nimport { cn } from "@/lib/utils";\r\nimport { AgentMessage } from "./agent-message";\r\n\r\nconst AGENT_NAME = "__EVE_INIT_APP_NAME__";\r\nconst BETA_TERMS_HREF = "https://vercel.com/docs/release-phases/public-beta-agreement";\r\n\r\ntype AgentStatus = ReturnType<typeof useEveAgent>["status"];\r\n\r\nexport function AgentChat() {\r\n  const agent = useEveAgent();\r\n  const isBusy = agent.status === "submitted" || agent.status === "streaming";\r\n  const isEmpty = agent.data.messages.length === 0;\r\n\r\n  const handleSubmit = async (message: PromptInputMessage) => {\r\n    const text = message.text.trim();\r\n    if (!text || isBusy) return;\r\n\r\n    await agent.send({ message: text });\r\n  };\r\n\r\n  const composer = (\r\n    <PromptInput onSubmit={handleSubmit}>\r\n      <PromptInputTextarea placeholder="Send a message…" />\r\n      <PromptInputSubmit onStop={agent.stop} status={agent.status} />\r\n    </PromptInput>\r\n  );\r\n\r\n  return (\r\n    <main className="flex h-dvh flex-col overflow-hidden bg-background text-foreground">\r\n      {isEmpty ? null : (\r\n        <header className="flex h-14 shrink-0 items-center justify-center gap-3 pl-4 pr-2">\r\n          <span className="flex min-w-0 items-center gap-2">\r\n            <span className="truncate text-muted-foreground text-sm">{AGENT_NAME}</span>\r\n            <StatusDot status={agent.status} />\r\n          </span>\r\n          <a\r\n            className="rounded-full border border-amber-500/30 px-2 py-0.5 font-medium text-amber-700 text-xs transition-colors hover:bg-amber-500/10 dark:text-amber-300"\r\n            href={BETA_TERMS_HREF}\r\n            rel="noreferrer"\r\n            target="_blank"\r\n          >\r\n            Public preview\r\n          </a>\r\n        </header>\r\n      )}\r\n\r\n      {agent.error ? (\r\n        <div className="mx-auto w-full max-w-3xl shrink-0 px-4 pt-2 sm:px-6">\r\n          <div className="flex items-start gap-3 rounded-lg border border-destructive/30 bg-destructive/5 px-3 py-2.5 text-sm">\r\n            <AlertCircleIcon className="mt-0.5 size-4 shrink-0 text-destructive" />\r\n            <div>\r\n              <p className="font-medium">Request failed</p>\r\n              <p className="mt-0.5 text-muted-foreground">{agent.error.message}</p>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      ) : null}\r\n\r\n      {isEmpty ? null : (\r\n        <Conversation className="min-h-0 flex-1">\r\n          <ConversationContent className="mx-auto w-full max-w-3xl gap-6 px-4 py-6 sm:px-6">\r\n            {agent.data.messages.map((message, index) => (\r\n              <AgentMessage\r\n                canRespond={!isBusy}\r\n                isStreaming={\r\n                  agent.status === "streaming" && index === agent.data.messages.length - 1\r\n                }\r\n                key={message.id}\r\n                message={message}\r\n                onInputResponses={(inputResponses) => agent.send({ inputResponses })}\r\n              />\r\n            ))}\r\n          </ConversationContent>\r\n          <ConversationScrollButton />\r\n        </Conversation>\r\n      )}\r\n\r\n      <div\r\n        className={cn(\r\n          "mx-auto w-full px-4 sm:px-6",\r\n          isEmpty\r\n            ? "flex max-w-xl flex-1 flex-col items-center justify-center gap-8 pb-[10vh]"\r\n            : "max-w-3xl shrink-0 pb-6",\r\n        )}\r\n      >\r\n        {isEmpty ? (\r\n          <div className="flex flex-col items-center gap-3 text-center">\r\n            <h1 className="font-medium text-5xl tracking-tighter">{AGENT_NAME}</h1>\r\n            <a\r\n              className="rounded-full border border-amber-500/30 px-2 py-0.5 font-medium text-amber-700 text-xs transition-colors hover:bg-amber-500/10 dark:text-amber-300"\r\n              href={BETA_TERMS_HREF}\r\n              rel="noreferrer"\r\n              target="_blank"\r\n            >\r\n              Public preview\r\n            </a>\r\n          </div>\r\n        ) : null}\r\n        <div className="w-full">{composer}</div>\r\n      </div>\r\n    </main>\r\n  );\r\n}\r\n\r\nfunction StatusDot({ status }: { readonly status: AgentStatus }) {\r\n  const isLive = status === "submitted" || status === "streaming";\r\n  const tone =\r\n    status === "error"\r\n      ? "bg-destructive"\r\n      : isLive\r\n        ? "bg-emerald-500"\r\n        : status === "ready"\r\n          ? "bg-muted-foreground"\r\n          : "bg-muted-foreground/50";\r\n\r\n  return (\r\n    <span className="relative flex size-1">\r\n      {isLive ? (\r\n        <span\r\n          className={cn(\r\n            "absolute inline-flex size-full animate-ping rounded-full opacity-75",\r\n            tone,\r\n          )}\r\n        />\r\n      ) : null}\r\n      <span className={cn("relative inline-flex size-1 rounded-full transition-colors", tone)} />\r\n    </span>\r\n  );\r\n}\r\n',
